mapper.sql:
 		from codeGroup as a
 		where 1=1
 			AND a.cg_use = #{shUseNy}		 
  	      	AND a.cg_delny = #{shDelNy}


					AND a.cg_register BETWEEN #{shDateStart} AND #{shDateEnd}
					AND a.cg_modifDate BETWEEN #{shDateStart} AND #{shDateEnd}


            AND a.cg_id = #{shValue}
            AND a.cg_name LIKE CONCAT('%',#{shValue},'%')
